def _matches_type(value: Any, expected: str) -> bool:
    if expected == "null":
        return value is None
    if expected == "boolean":
        return isinstance(value, bool)
    if expected == "integer":
        return isinstance(value, int) and not isinstance(value, bool)
    if expected == "number":
        return isinstance(value, (int, float)) and not isinstance(value, bool)
    if expected == "string":
        return isinstance(value, str)
    if expected == "array":
        return isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray))
    if expected == "object":
        return isinstance(value, Mapping)
    return False

def _resolve_ref(root: Mapping[str, Any], reference: str) -> Any:
    if not reference.startswith("#/"):
        return None
    current: Any = root
    for raw_part in reference[2:].split("/"):
        part = raw_part.replace("~1", "/").replace("~0", "~")
        if not isinstance(current, Mapping) or part not in current:
            return None
        current = current[part]
    return current

def _validate_node(value: Any, node: Mapping[str, Any], path: str, errors: list[str], root: Mapping[str, Any]) -> None:
    reference = node.get("$ref")
    if isinstance(reference, str):
        target = _resolve_ref(root, reference)
        if not isinstance(target, Mapping):
            errors.append(f"{path} unresolved schema reference {reference}")
        else:
            _validate_node(value, target, path, errors, root)
        return
    if "const" in node and value != node["const"]:
        errors.append(f"{path} must equal {node['const']!r}")
    if "enum" in node and value not in node["enum"]:
        errors.append(f"{path} must be an allowed enum value")
    for child in node.get("allOf", ()):
        _validate_node(value, child, path, errors, root)
    for keyword in ("oneOf", "anyOf"):
        branches = node.get(keyword)
        if not branches:
            continue
        matches = 0
        for child in branches:
            branch_errors: list[str] = []
            _validate_node(value, child, path, branch_errors, root)
            if not branch_errors:
                matches += 1
        if (keyword == "oneOf" and matches != 1) or (keyword == "anyOf" and matches < 1):
            errors.append(f"{path} must match {keyword}")
    raw_types = node.get("type")
    expected_types = raw_types if isinstance(raw_types, list) else [raw_types] if raw_types else []
    if expected_types and not any(_matches_type(value, expected) for expected in expected_types):
        errors.append(f"{path} must be {' or '.join(expected_types)}")
        return
    if isinstance(value, str):
        if "minLength" in node and len(value) < node["minLength"]:
            errors.append(f"{path} must have length >= {node['minLength']}")
        if "maxLength" in node and len(value) > node["maxLength"]:
            errors.append(f"{path} must have length <= {node['maxLength']}")
        if "pattern" in node and re.search(node["pattern"], value) is None:
            errors.append(f"{path} must match pattern")
        if node.get("format") == "date-time":
            try:
                datetime.fromisoformat(value.replace("Z", "+00:00"))
            except ValueError:
                errors.append(f"{path} must be an ISO date-time")
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if "minimum" in node and value < node["minimum"]:
            errors.append(f"{path} must be >= {node['minimum']}")
        if "maximum" in node and value > node["maximum"]:
            errors.append(f"{path} must be <= {node['maximum']}")
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        if "minItems" in node and len(value) < node["minItems"]:
            errors.append(f"{path} must contain >= {node['minItems']} items")
        if "maxItems" in node and len(value) > node["maxItems"]:
            errors.append(f"{path} must contain <= {node['maxItems']} items")
        if node.get("uniqueItems") and len({json.dumps(item, sort_keys=True) for item in value}) != len(value):
            errors.append(f"{path} must contain unique items")
        item_schema = node.get("items", {})
        for index, item in enumerate(value):
            _validate_node(item, item_schema, f"{path}/{index}", errors, root)
    if isinstance(value, Mapping):
        properties = node.get("properties", {})
        for name in node.get("required", ()):
            if name not in value:
                errors.append(f"{path}/{name} is required")
        for name, child in properties.items():
            if name in value:
                _validate_node(value[name], child, f"{path}/{name}", errors, root)
        for name, child_value in value.items():
            if name in properties:
                continue
            additional = node.get("additionalProperties")
            if additional is False:
                errors.append(f"{path}/{name} additional property is not allowed")
            elif isinstance(additional, Mapping):
                _validate_node(child_value, additional, f"{path}/{name}", errors, root)

def validate_protocol_message(value: object) -> tuple[bool, tuple[str, ...]]:
    errors: list[str] = []
    _validate_node(value, CC_AGENT_PROTOCOL_SCHEMA, "#", errors, CC_AGENT_PROTOCOL_SCHEMA)
    return not errors, tuple(errors)

def validate_protocol_definition(name: str, value: object) -> tuple[bool, tuple[str, ...]]:
    definitions = CC_AGENT_PROTOCOL_SCHEMA.get("$defs", {})
    definition = definitions.get(name) if isinstance(definitions, Mapping) else None
    if not isinstance(definition, Mapping):
        return False, (f"# unknown protocol definition {name}",)
    errors: list[str] = []
    _validate_node(value, definition, "#", errors, CC_AGENT_PROTOCOL_SCHEMA)
    return not errors, tuple(errors)

def validate_approval_decision(value: object) -> tuple[bool, tuple[str, ...]]:
    return validate_protocol_definition("ApprovalDecision", value)

def validate_agent_stream_event(value: object) -> tuple[bool, tuple[str, ...]]:
    return validate_protocol_definition("AgentStreamEventEnvelope", value)

def validate_canonical_agent_stream_event(value: object) -> tuple[bool, tuple[str, ...]]:
    return validate_protocol_definition("CanonicalAgentStreamEvent", value)

